/* Lophus Football Fun — UI */
const $=s=>document.querySelector(s);
const V=$('#view');
const IC={
home:'<path d="M3 11l9-7 9 7v9a1 1 0 01-1 1h-5v-6H9v6H4a1 1 0 01-1-1z" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>',
squad:'<path d="M8 3l-5 3 2 4 2-1v12h10V9l2 1 2-4-5-3c0 2-2 3-4 3S8 5 8 3z" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>',
scout:'<circle cx="10.5" cy="10.5" r="6.5" fill="none" stroke="currentColor" stroke-width="2"/><path d="M15.5 15.5L21 21" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/>',
transfers:'<path d="M4 8h14l-4-4M20 16H6l4 4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>',
mail:'<rect x="3" y="5" width="18" height="14" rx="2" fill="none" stroke="currentColor" stroke-width="2"/><path d="M3 7l9 6 9-6" fill="none" stroke="currentColor" stroke-width="2"/>',
more:'<rect x="4" y="4" width="7" height="7" rx="1.5" fill="none" stroke="currentColor" stroke-width="2"/><rect x="13" y="4" width="7" height="7" rx="1.5" fill="none" stroke="currentColor" stroke-width="2"/><rect x="4" y="13" width="7" height="7" rx="1.5" fill="none" stroke="currentColor" stroke-width="2"/><rect x="13" y="13" width="7" height="7" rx="1.5" fill="none" stroke="currentColor" stroke-width="2"/>',
cup:'<path d="M7 4h10v5a5 5 0 01-10 0zM7 6H4v2a3 3 0 003 3M17 6h3v2a3 3 0 01-3 3M12 14v4M8 21h8M9 18h6" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>',
bolt:'<path d="M13 2L4 14h7l-1 8 9-12h-7z" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>',
star:'<path d="M12 3l2.7 5.6 6.1.9-4.4 4.3 1 6.1L12 17l-5.4 2.9 1-6.1-4.4-4.3 6.1-.9z" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>',
key:'<circle cx="8" cy="15" r="4" fill="none" stroke="currentColor" stroke-width="2"/><path d="M11 12l9-9M17 6l3 3M15 8l2 2" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>',
coin:'<ellipse cx="12" cy="7" rx="7" ry="3" fill="none" stroke="currentColor" stroke-width="2"/><path d="M5 7v10c0 1.7 3.1 3 7 3s7-1.3 7-3V7M5 12c0 1.7 3.1 3 7 3s7-1.3 7-3" fill="none" stroke="currentColor" stroke-width="2"/>',
flask:'<path d="M9 3h6M10 3v6L4 19a1.5 1.5 0 001.3 2h13.4A1.5 1.5 0 0020 19l-6-10V3" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/><path d="M7 15h10" stroke="currentColor" stroke-width="2"/>',
book:'<path d="M4 4h7a2 2 0 012 2v14a2 2 0 00-2-2H4zM20 4h-7a2 2 0 00-2 2v14a2 2 0 012-2h7z" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>',
staff:'<circle cx="9" cy="8" r="3.5" fill="none" stroke="currentColor" stroke-width="2"/><path d="M3 20c0-3.5 2.7-6 6-6s6 2.5 6 6M16 4.5a3.5 3.5 0 010 7M21 20c0-3-1.7-5.3-4-5.9" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>'};
const icon=(n,s=24)=>`<svg viewBox="0 0 24 24" width="${s}" height="${s}" aria-hidden="true">${IC[n]||IC.more}</svg>`;
const ovrCol=v=>v>=80?'var(--grn)':v>=65?'var(--ink)':v>=52?'var(--gold)':'var(--red2)';
const moCol=v=>v>=70?'var(--grn)':v>=45?'var(--gold)':'var(--red)';
const tierStyle=t=>t===0?'background:linear-gradient(90deg,#ff4fd8,#ffd84a,#3fcf7d,#3d8bfd,#9b5de5);color:#fff':`background:${tierCol(t)};color:${t===1||t===8?'#17191a':'#fff'}`;
const skPill=(id,opts='')=>{const s=SK[id];if(!s)return'';return `<span class="tpill" data-sk="${id}" style="${tierStyle(s.t)}" ${opts}>${s.act?'⚡ ':''}${esc(s.n)}</span>`};
const tierDots=p=>p.tr&&p.tr.length?p.tr.slice().sort((a,b)=>tierOf(a)-tierOf(b)).slice(0,4).map(id=>`<i class="tdot" style="${tierStyle(tierOf(id))}" data-sk="${id}"></i>`).join(''):'';
function prow(p,opts={}){const f=p.club===S.me.cid||!opts.club?fitC(p):fitC(p);const c=S.clubs[p.club];return `<button class="li" data-a="player:${p.id}"><span class="num" style="background:${c?c.col:'#777'}">${p.num||'–'}</span><span style="flex:1"><span class="b">${p.gem?'💎 ':''}${esc(p.name)}</span> ${tierDots(p)}<br><span class="row sm mut" style="gap:6px;flex-wrap:wrap"><span class="pos ${p.pos}">${p.pos}</span>${p.age}y${opts.club&&c?' · '+esc(c.name):''}${!p.club?' · free agent':''}${p.inj>0?` <span class="chip r">inj ${p.inj}d</span>`:''}${p.ban>0?' <span class="chip r">banned</span>':''}${S.me.force.includes(p.id)?' <span class="chip bl">starts</span>':''}</span></span>${opts.val?`<span class="sm mut">${money(opts.val===2?(p.club?p.val:faFee(p)):p.val)}</span>`:''}<span class="dot" style="background:${moCol(p.mo)}" title="Morale"></span><span style="text-align:right"><span class="ovr" style="color:${ovrCol(p.ovr)}">${p.ovr}</span><br><span class="sm mut">fit ${f}</span></span></button>`}
function tabs(key,list){const cur=S.ui.tab[key]||list[0][0];return `<div class="tabs" role="tablist">${list.map(([k,l])=>`<button role="tab" class="${cur===k?'on':''}" data-a="tab:${key}:${k}">${l}</button>`).join('')}</div>`}
function subtabs(key,list){const cur=S.ui.tab[key]||list[0][0];return `<div style="margin-bottom:10px">${list.map(([k,l])=>`<button class="pill ${cur===k?'on':''}" data-a="tab:${key}:${k}">${l}</button>`).join('')}</div>`}
const tab=(key,def)=>S.ui.tab[key]||def;
function toast(t){const el=$('#toast');el.textContent=t;el.style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>el.style.display='none',3000)}
function modal(h){$('#sheet').innerHTML=h;$('#modal').classList.add('on')}
function closeModal(){$('#modal').classList.remove('on')}
$('#modal').addEventListener('click',e=>{if(e.target.id==='modal'&&!RUN)closeModal()});
function bars(lbl,v,cls=''){return `<div><div class="row"><span class="lbl">${lbl}</span><span class="sp b">${Math.round(v)}</span></div><div class="bar ${cls}"><i style="width:${cl(v,0,100)}%"></i></div></div>`}
function go(pg){S.ui.pg=pg;window.scrollTo(0,0);render()}
const back=(pg='more')=>`<button class="btn sm" data-a="go:${pg}">Back</button>`;

/* ---------- top + nav ---------- */
function renderTop(){if(!S||!S.me){$('#top').style.display='none';$('#nav').style.display='none';return}
  const c=me();$('#top').style.display='flex';
  $('#top').innerHTML=`${crest(c,32)}<div><div class="t1">${esc(c.name)}</div><div class="t2">${lgName(c)} · ${esc(S.me.name)}, manager</div></div><div class="right"><div class="date">${fmtD(S.d)}</div><div class="t2" style="font-weight:700"><span style="color:${S.me.money<0?'var(--red2)':'var(--grn)'}">${money(S.me.money)}</span> · 🌱${S.me.seeds}</div></div>`;
  const un=S.mail.filter(m=>!m.read).length;const open=S.tr.inc.filter(x=>x.st==='open').length+S.tr.out.filter(x=>x.st==='countered').length;const pg=S.ui.pg;const grp={home:'home',match:'home',squad:'squad',scout:'scout',transfers:'transfers',mail:'mail'};
  $('#nav').style.display=LM&&!LM.done?'none':'';
  $('#nav').innerHTML=[['home','Home'],['squad','Squad'],['scout','Scout'],['transfers','Transfers'],['mail','Mail'],['more','More']].map(([k,l])=>`<button class="${(grp[pg]||'more')===k?'on':''}" data-a="go:${k}">${icon(k)}<span>${l}</span>${k==='mail'&&un?`<span class="badge">${un}</span>`:''}${k==='transfers'&&open?`<span class="badge">${open}</span>`:''}</button>`).join('');
}

/* ---------- pages ---------- */
const P={};
P.home=()=>{
  const c=me(),nf=nextFixture(),tb=table(c.lg),pos=tb.findIndex(r=>r.c===c.id)+1;const today=myFixtureToday();
  let nm='<div class="empty">No fixtures left this season. Continue to the season review.</div>';
  if(nf){const H=S.clubs[nf.h],A=S.clubs[nf.a];nm=`<div class="row sm" style="margin-bottom:10px"><span class="lbl">Next match · ${shortD(nf.d)}</span><span class="sp chip ${today?'r':''}">${today?'Today':`Round ${nf.r}`}</span></div><div class="match"><div>${crest(H,58)}<div class="nm">${esc(H.name)}</div><div class="sm mut">OVR ${avgOvr(H.id)} · ${statusOf(H)[0]}</div></div><div class="disp mut" style="font-size:26px">v</div><div>${crest(A,58)}<div class="nm">${esc(A.name)}</div><div class="sm mut">OVR ${avgOvr(A.id)} · ${statusOf(A)[0]}</div></div></div>`}
  const st=cl(pos-3,0,Math.max(0,tb.length-5));const near=tb.slice(st,st+5);
  const form=S.me.res.slice(-5).map(r=>`<i class="${r.gf>r.ga?'W':r.gf<r.ga?'L':'D'}">${r.gf>r.ga?'W':r.gf<r.ga?'L':'D'}</i>`).join('')||'<span class="sm mut">No games yet</span>';
  const ex=expectation();const avgMo=Math.round(sq(c.id).reduce((s,p)=>s+p.mo,0)/(sq(c.id).length||1));
  const un=S.mail.filter(m=>!m.read).slice(0,3);const[ts,tk]=trustState(),[bs,bk]=boardState();
  return `<div class="card">${nm}<div class="grid2" style="margin-top:14px">${today?`<button class="btn pri wide" data-a="go:match" style="grid-column:1/-1">Go to match</button>`:`<button class="btn pri" data-a="run:cont">Continue</button><button class="btn" data-a="run:match">Next match</button>`}</div></div>
  <div class="grid4" style="margin-bottom:14px">
   <div class="card" style="margin:0"><div class="lbl">Position</div><div class="big">${pos?ord(pos):'–'}</div><div class="sm mut">target ${ord(ex.tgt)}</div></div>
   <div class="card" style="margin:0"><div class="lbl">Fans</div><div class="big">${Math.round(c.fans)}</div><div class="bar" style="margin-top:6px"><i style="width:${c.fans}%"></i></div></div>
   <div class="card" style="margin:0"><div class="lbl">Squad morale</div><div class="big" style="color:${moCol(avgMo)}">${avgMo}</div><div class="sm mut">${sq(c.id).length} players</div></div>
   <div class="card" style="margin:0"><div class="lbl">Form</div><div class="form" style="margin-top:8px">${form}</div></div>
  </div>
  <button class="card row" style="width:100%;text-align:left;cursor:pointer" data-a="go:staff"><span style="flex:1"><span class="lbl">Coach trust</span><br><span class="chip ${tk}">${ts}</span></span><span style="flex:1"><span class="lbl">Board</span><br><span class="chip ${bk}">${bs}</span></span><span style="flex:1"><span class="lbl">Leaders</span><br><span class="chip ${leadState()[1]}">${leadState()[0]}</span></span></button>
  <div class="card"><div class="row" style="margin-bottom:6px"><h3>${lgName(c)}</h3><button class="btn sm sp" data-a="go:league">Full table</button></div><table><tr><th>#</th><th class="cl">Club</th><th>P</th><th>GD</th><th>Pts</th></tr>${near.map(r=>{const i=tb.indexOf(r)+1;return `<tr class="${r.c===c.id?'me':''}"><td>${i}</td><td class="cl">${esc(S.clubs[r.c].name)}</td><td>${r.p}</td><td>${r.gf-r.ga}</td><td class="b">${r.pts}</td></tr>`}).join('')}</table></div>
  <div class="card"><div class="row" style="margin-bottom:4px"><h3>Inbox</h3><button class="btn sm sp" data-a="go:mail">All mail</button></div>${un.length?un.map(mrow).join(''):'<div class="empty">All caught up.</div>'}</div>`};

function mrow(m){const[ic,bg]=MI[m.cat]||MI.club;return `<button class="li" data-a="openmail:${m.id}"><span class="mi" style="background:${bg}">${ic}</span><span style="flex:1"><span class="row sm mut" style="gap:6px">${esc(m.from)} · ${shortD(m.d)}${m.imp&&!m.done?' <span class="chip y">Action</span>':''}</span><span class="b" style="display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(m.title)}</span></span>${m.read?'':'<span class="unread"></span>'}</button>`}
P.mail=()=>{const t=tab('mail','unread');const f={unread:m=>!m.read,all:()=>true,transfer:m=>m.cat==='transfer'||m.cat==='scout',squad:m=>['squad','medical','staff'].includes(m.cat),club:m=>['club','money','media','award'].includes(m.cat)}[t];const list=S.mail.filter(f);const un=S.mail.filter(m=>!m.read).length;
  return `<div class="row" style="margin-bottom:12px"><div><h1>Inbox</h1><div class="mut">${un} unread</div></div><button class="btn sm sp" data-a="markall">Mark all read</button></div>${tabs('mail',[['unread','Unread'],['all','All'],['transfer','Transfers'],['squad','Squad'],['club','Club']])}<div class="card">${list.length?list.map(mrow).join(''):'<div class="empty">Nothing here.</div>'}</div>`};
function openMail(id,prev){const m=S.mail.find(x=>x.id==id);if(!m)return;m.read=true;const M=MT[m.type];const acts=!m.done&&M.acts?M.acts(m.data):null;const pend=S.mail.filter(x=>!x.done&&x.id!==m.id).length;
  modal(`${prev?`<div class="card flat b" style="margin-bottom:10px;border-left:4px solid var(--grn)">✓ ${esc(prev)}</div>`:''}<div class="row" style="margin-bottom:10px"><span class="mi" style="background:${(MI[m.cat]||MI.club)[1]}">${(MI[m.cat]||MI.club)[0]}</span><div><div class="lbl">${esc(m.from)} · ${fmtD(m.d)}</div><h2>${esc(m.title)}</h2></div></div><div>${M.body(m.data)}</div>${m.res?`<div class="card flat" style="margin-top:10px"><span class="lbl">Outcome</span><br>${esc(m.res)}</div>`:''}<div class="row wrap" style="margin-top:14px">${acts?acts.map(([k,l,c])=>`<button class="btn ${c}" data-a="mact:${m.id}:${k}">${esc(l)}</button>`).join(''):''}<button class="btn ghost sp" data-a="close">Close</button></div>${acts&&RUNMODE?`<p class="note">After you decide, the game moves on${pend?` to the next of ${pend} waiting mail`:' and keeps simulating'} by itself.</p>`:''}`);renderTop();}

P.squad=()=>{const t=tab('squad','coach');return `<h1 style="margin-bottom:12px">Squad</h1>${tabs('squad',[['coach','Coach'],['players','Players'],['xi','Line-up'],['plan','Transfer plan']])}${({coach:sqCoach,players:sqPlayers,xi:sqXI,plan:sqPlan})[t]()}`};
function sqCoach(){const co=coachOf(S.me.cid);if(!co)return'<div class="card empty">No head coach. Hire one in Scout › Coaches.</div>';const w=TAC[co.tac];const mx=Math.max(...w);const[ts,tk]=trustState();
  return `<div class="card"><div class="lbl" style="color:var(--grn)">Head coach</div><div class="row"><h2>${esc(co.name)}</h2><span class="sp chip">${NATN[co.nat]} · ${co.age}y</span></div><div class="sm mut">${money(co.wage)}/month${co.aw.length?` · ${co.aw.length} award${co.aw.length>1?'s':''}`:''} · trust in you <span class="chip ${tk}">${ts}</span></div>
  <div class="grid2" style="margin:14px 0"><div><div class="lbl">Playing style</div><div class="disp" style="font-size:24px;color:var(--red2)">${co.tac}</div><div class="sm mut">${TACD[co.tac]}</div></div><div><div class="lbl">Formation</div><div class="disp" style="font-size:24px;color:var(--red2)">${co.form}</div></div></div>
  <div class="grid3">${bars('Tactical',co.ta,'gd')}${bars('Development',co.dv,'gd')}${bars('Man mgmt',co.mm,'gd')}</div><p class="note">Effective tactical rating right now: ${Math.round(coachTa(S.me.cid))} (trust ${Math.round(S.me.trust)}). Stat boost from the coach: +${cboost(S.me.cid)} on every stat.</p></div>
  <div class="card"><div class="row"><h3>Preferred profile</h3><span class="sp sm mut">set by ${co.tac}</span></div><div class="grid4" style="margin-top:10px">${ATT.map((k,i)=>`<div class="prof ${w[i]===mx?'top':''}"><div class="lbl">${AL[k]}</div><div class="big">${w[i]}%</div><div class="note">${w[i]>=35?'+2 boost':w[i]>=25?'+1 boost':'no boost'}</div></div>`).join('')}</div><p class="sm mut" style="margin-bottom:0">Change the style and the profile changes with it. Players strong in the favoured stats get a higher <b>fit</b> and start more often.</p></div>
  <div class="card"><h3>Your requests to the coach</h3><p class="sm mut">${boss()?'Final Say is on: he will do whatever you ask.':'He may refuse, depending on man management and how much he trusts you.'}</p>
  <label class="f"><span>Playing style</span><select id="rqTac">${Object.keys(TAC).map(k=>`<option ${k===co.tac?'selected':''}>${k}</option>`).join('')}</select></label>
  <label class="f"><span>Formation</span><select id="rqForm">${Object.keys(FORMS).map(k=>`<option ${k===co.form?'selected':''}>${k}</option>`).join('')}</select></label>
  <div class="row wrap"><button class="btn grn" data-a="coachreq">Send request</button><button class="btn" data-a="tabgo:scout:coaches">Replace coach</button></div></div>`}
function sqPlayers(){const f=S.ui.pf||'ALL',srt=S.ui.ps||'ovr';let l=sq(S.me.cid).filter(p=>f==='ALL'||p.pos===f);
  const key={ovr:p=>-p.ovr,fit:p=>-fitC(p),pot:p=>-p.pot,age:p=>p.age,val:p=>-p.val,pos:p=>PI[p.pos]*100-p.ovr,mo:p=>-p.mo,tr:p=>bestTier(p)}[srt];l.sort((a,b)=>key(a)-key(b));
  return `<div style="margin-bottom:8px">${['ALL',...POSL].map(x=>`<button class="pill ${f===x?'on':''}" data-a="pf:${x}">${x==='ALL'?'All':x}</button>`).join('')}</div><div class="row" style="margin-bottom:10px"><span class="lbl">Sort</span><select id="psort" style="max-width:180px">${[['ovr','OVR'],['fit','Fit'],['pot','Potential'],['tr','Best skill'],['pos','Position'],['age','Age'],['val','Value'],['mo','Morale']].map(([k,l])=>`<option value="${k}" ${k===srt?'selected':''}>${l}</option>`).join('')}</select><span class="sp sm mut">${l.length} · wages ${money(sq(S.me.cid).reduce((s,p)=>s+p.wage,0))}/mo</span></div><div class="card">${l.map(p=>prow(p,{val:1})).join('')||'<div class="empty">None</div>'}</div>`}
function pitchSVG(L,col){const w=340,h=470;return `<svg viewBox="0 0 ${w} ${h}" style="width:100%;max-width:440px;display:block;margin:0 auto" role="img" aria-label="Line-up"><rect width="${w}" height="${h}" rx="14" fill="var(--pitch)"/>${[0,1,2,3,4,5].map(i=>`<rect y="${i*h/6}" width="${w}" height="${h/12}" fill="var(--pitch2)"/>`).join('')}<g fill="none" stroke="rgba(255,255,255,.55)" stroke-width="1.5"><rect x="14" y="14" width="${w-28}" height="${h-28}"/><line x1="14" y1="${h/2}" x2="${w-14}" y2="${h/2}"/><circle cx="${w/2}" cy="${h/2}" r="40"/><rect x="${w/2-70}" y="${h-14-60}" width="140" height="60"/><rect x="${w/2-70}" y="14" width="140" height="60"/></g>${L.xi.map((p,i)=>{const[sp,x,y]=L.slots[i];const cx=20+x*(w-40),cy=h-24-y*(h-60)/.78;if(!p)return'';const pn2=pen(p.pos,sp);return `<g data-a="player:${p.id}" style="cursor:pointer"><circle cx="${cx}" cy="${cy}" r="15" fill="${col}" stroke="#fff" stroke-width="2"/><text x="${cx}" y="${cy+5}" text-anchor="middle" fill="#fff" font-family="Big Shoulders Display" font-weight="800" font-size="15">${p.num}</text><rect x="${cx-34}" y="${cy+17}" width="68" height="17" rx="5" fill="rgba(0,0,0,.45)"/><text x="${cx}" y="${cy+29}" text-anchor="middle" fill="#fff" font-size="11" font-weight="600">${esc(last(p.name)).slice(0,11)}</text><rect x="${cx+8}" y="${cy-22}" width="22" height="14" rx="4" fill="#fff"/><text x="${cx+19}" y="${cy-11}" text-anchor="middle" font-size="10" font-weight="700" fill="${pn2?'#c3311c':'#18804a'}">${L.fc[p.id]-pn2}</text></g>`}).join('')}</svg>`}
function sqXI(){const L=pickXI(S.me.cid);return `<div class="card"><div class="row" style="margin-bottom:8px"><div><div class="lbl">${esc(coName())} picks the team</div><h3>${L.form} · ${L.tac}</h3></div><span class="sp chip">Strength ${Math.round(strength(S.me.cid,L))}</span></div>${pitchSVG(L,me().col)}<p class="sm mut">Badges show each player's fit for his slot. Tap a player to ask the coach to start him.</p>${S.me.force.length?`<button class="btn sm" data-a="clearforce">Clear my start requests (${S.me.force.length})</button>`:''}</div><div class="card"><h3>Bench</h3>${L.bench.map(p=>prow(p)).join('')||'<div class="empty">No bench</div>'}</div>`}
function sqPlan(){const{weak,off,co}=coachPlan();const w=TAC[co.tac];const emph=ATT[w.indexOf(Math.max(...w))];
  return `<div class="card flat sm">Following this plan builds the coach's trust. Signing players he didn't ask for, or selling his starters, breaks it. See More › Staff.</div><div class="card"><h3>Players to sign</h3><p class="sm mut">${esc(coName())} wants ${ALF[emph]} for ${co.tac}.</p>${weak.length?weak.map(ps=>`<div class="row" style="padding:8px 0;border-top:1px solid var(--line)"><span class="pos ${ps}">${ps}</span><span>Upgrade wanted</span><button class="btn sm sp" data-a="brief:${ps}:${emph}">Brief agency · ${money(agFee())}</button></div>`).join(''):'<div class="empty">Happy with the starting eleven.</div>'}</div>
  <div class="card"><h3>Players to offload</h3><p class="sm mut">“Everywhere these lads play, I already have better options. Sell and free the wages.”</p>${off.map(p=>prow(p,{val:1})).join('')||'<div class="empty">No surplus players.</div>'}${off.length?`<button class="btn sm" data-a="listall">Put all ${off.length} up for sale</button>`:''}</div>`}

P.scout=()=>{const t=tab('scout','search');return `<h1 style="margin-bottom:12px">Scouting</h1>${tabs('scout',[['search','Search'],['agency','Agency'],['reports','Reports'],['short','Shortlist'],['coaches','Coaches']])}${({search:scSearch,agency:scAgency,reports:scReports,short:scShort,coaches:scCoaches})[t]()}`};
function scSearch(){const q=S.ui.q||{pos:'ALL',min:0,age:40,max:0,scope:'near'};const mq=lq(me());
  let l=Object.values(S.P).filter(p=>p.club!==S.me.cid&&!p.yth&&(q.pos==='ALL'||p.pos===q.pos)&&p.ovr>=q.min&&p.age<=q.age&&(!q.max||p.val<=q.max*1e3)&&(q.scope==='all'||(p.club?Math.abs(lq(S.clubs[p.club])-mq)<=8:true)));
  l.sort((a,b)=>fitC(b)-fitC(a));const n=l.length;l=l.slice(0,40);
  return `<div class="card"><div class="grid2"><label class="f"><span>Position</span><select id="qpos">${['ALL',...POSL].map(x=>`<option ${q.pos===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="f"><span>Min OVR</span><input type="number" id="qmin" value="${q.min}" min="0" max="99"></label><label class="f"><span>Max age</span><input type="number" id="qage" value="${q.age}" min="15" max="45"></label><label class="f"><span>Max value (€K, 0 = any)</span><input type="number" id="qmax" value="${q.max}" min="0"></label></div><label class="f"><span>Where</span><select id="qscope"><option value="near" ${q.scope==='near'?'selected':''}>Leagues near our level</option><option value="all" ${q.scope==='all'?'selected':''}>Every division</option></select></label><button class="btn grn" data-a="search">Search</button></div><div class="sm mut" style="margin:0 4px 8px">${n} found · sorted by fit for our style</div><div class="card">${l.map(p=>prow(p,{club:1,val:2})).join('')||'<div class="empty">No matches.</div>'}</div>`}
const agFee=()=>[60e3,30e3,12e3,5e3,2e3][me().t-1];
function scAgency(){return `<div class="card"><h3>Brief the agency</h3><p class="sm mut">The agency finds brand-new players who match your brief and files a report. Network level ${S.me.fac.sc}/5 lifts their quality. ${boss()||S.me.unl.eyes?'Your brief is guaranteed.':'Some names may fall short of the brief.'}</p>
  <div class="grid2"><label class="f"><span>Position</span><select id="apos">${POSL.map(x=>`<option>${x}</option>`).join('')}</select></label><label class="f"><span>Main strength</span><select id="aemph">${ATT.map(k=>`<option value="${k}">${ALF[k]}</option>`).join('')}</select></label><label class="f"><span>Min OVR</span><input type="number" id="amin" value="${avgOvr(S.me.cid)}" min="25" max="95"></label><label class="f"><span>Max age</span><input type="number" id="aage" value="27" min="17" max="36"></label></div>
  <label class="f"><span>How many</span><select id="an"><option>3</option><option selected>5</option><option>8</option></select></label><button class="btn pri wide" data-a="agency">Brief the agency · ${money(agFee())}</button></div>`}
function scReports(){return S.rep.length?S.rep.map(r=>`<div class="card"><div class="row"><div><div class="lbl">${esc(r.src)} · ${fmtD(r.d)}</div><div class="b">${esc(r.title)}</div></div><span class="sp big" style="font-size:28px">${r.pids.filter(id=>S.P[id]).length}</span></div>${r.rev?r.pids.map(id=>S.P[id]).filter(Boolean).map(p=>prow(p,{club:1,val:2})).join(''):`<button class="btn grn sm" style="margin-top:10px" data-a="reveal:${r.id}">Reveal names</button>`}</div>`).join(''):'<div class="card empty">No reports yet. Scouts file them as the season runs, or brief the agency.</div>'}
function scShort(){const l=S.me.short.map(id=>S.P[id]).filter(Boolean);return `<div class="card">${l.length?l.map(p=>prow(p,{club:1,val:2})).join(''):'<div class="empty">Nobody on the list.</div>'}</div>`}
function scCoaches(){const co=coachOf(S.me.cid);const card=(c,cur)=>`<div class="card"><div class="row"><div><div class="b">${esc(c.name)} <span class="mut sm">${NATN[c.nat]} · ${c.age}y</span></div><div class="sm"><span class="chip">${c.tac}</span> <span class="chip">${c.form}</span></div></div><div class="sp sm mut" style="text-align:right">${money(c.wage)}/mo</div></div><div class="grid3" style="margin-top:10px">${bars('Tactical',c.ta,'gd')}${bars('Development',c.dv,'gd')}${bars('Man mgmt',c.mm,'gd')}</div><div class="note" style="margin-top:6px">Wants: ${ATT.map((k,i)=>`${AL[k]} ${TAC[c.tac][i]}%`).join(' · ')}</div>${cur?'<div class="chip g" style="margin-top:10px">Current head coach</div>':`<button class="btn grn sm" style="margin-top:10px" data-a="hire:${c.id}">Hire</button>`}</div>`;
  return `${co?card(co,1):''}<div class="lbl" style="margin:4px 4px 8px">Available coaches · refreshed monthly · sacking costs 3 months' wages</div>${S.pool.map(id=>S.C[id]).filter(Boolean).map(c=>card(c,0)).join('')}`}

P.transfers=()=>{const t=tab('tr','overview');return `<h1 style="margin-bottom:12px">Transfers</h1>${tabs('tr',[['overview','Overview'],['inc','Incoming'],['out','Outgoing'],['hist','History']])}${({overview:trOverview,inc:trInc,out:trOut,hist:trHist2})[t]()}`};
function trOverview(){const inc=S.tr.inc.filter(x=>x.st==='open'),out=S.tr.out.filter(x=>x.st==='pending'||x.st==='countered');const yr=S.tr.hist.filter(h=>h.s===S.season);const spent=yr.filter(h=>h.dir==='in').reduce((s,h)=>s+h.fee,0),got=yr.filter(h=>h.dir==='out').reduce((s,h)=>s+h.fee,0);const{weak,off}=coachPlan();
  return `<div class="card"><div class="row"><div><div class="lbl">Budget</div><div class="big" style="color:${S.me.money<0?'var(--red2)':'var(--grn)'}">${money(S.me.money)}</div></div><span class="sp chip ${inWindow()?'g':''}">${inWindow()?'Window open: clubs are busy':'Window quiet'}</span></div><div class="grid3" style="margin-top:12px"><div><div class="lbl">Spent ${seasonLbl(S.season)}</div><div class="b">${money(spent)}</div></div><div><div class="lbl">Received</div><div class="b">${money(got)}</div></div><div><div class="lbl">Net</div><div class="b" style="color:${got-spent>=0?'var(--grn)':'var(--red2)'}">${money(got-spent)}</div></div></div></div>
  <div class="grid2"><button class="card" style="text-align:left;cursor:pointer;margin:0" data-a="tab:tr:inc"><div class="lbl">Offers for our players</div><div class="big">${inc.length}</div><div class="sm mut">waiting for your answer</div></button><button class="card" style="text-align:left;cursor:pointer;margin:0" data-a="tab:tr:out"><div class="lbl">Our offers</div><div class="big">${out.length}</div><div class="sm mut">pending or countered</div></button></div>
  <div class="card" style="margin-top:14px"><h3>Coach's plan</h3><p class="sm">Wants: ${weak.length?weak.map(x=>`<span class="pos ${x}">${x}</span>`).join(' '):'nothing urgent'} · Surplus: ${off.length} player${off.length===1?'':'s'}</p><button class="btn sm" data-a="tabgo:squad:plan">Open transfer plan</button></div>`}
function trInc(){const l=S.tr.inc.slice(0,40);return l.length?l.map(x=>{const p=S.P[x.pid];const c=S.clubs[x.club];const open=x.st==='open';return `<div class="card"><div class="row"><div style="flex:1"><div class="lbl">${esc(c?.name)} · ${fmtD(x.d)}</div><div class="b">${esc(p?p.name:'Former player')} ${p?`<span class="pos ${p.pos}">${p.pos}</span> OVR ${p.ovr}`:''}</div><div class="sm mut">Offer ${money(x.fee)}${p?` · value ${money(p.val)}`:''}${open?` · expires ${shortD(x.exp)}`:''}</div></div><span class="chip ${open?'y':x.st==='accepted'?'g':''}">${({open:'Open',accepted:'Sold',rejected:'Rejected',expired:'Expired',walked:'Walked away'})[x.st]||x.st}</span></div>${open&&p?`<div class="row wrap" style="margin-top:10px"><button class="btn grn sm" data-a="incacc:${x.id}">Accept</button><button class="btn sm" data-a="incctr:${x.id}">Ask for 30% more</button><button class="btn sm" data-a="increj:${x.id}">Reject</button><button class="btn sm ghost" data-a="player:${p.id}">View</button></div>`:''}</div>`}).join(''):'<div class="card empty">No offers yet. List players for sale from their profile or the transfer plan.</div>'}
function trOut(){const l=S.tr.out.slice(0,40);return l.length?l.map(x=>{const p=S.P[x.pid];const c=S.clubs[x.from];return `<div class="card"><div class="row"><div style="flex:1"><div class="lbl">to ${esc(c?.name)} · ${fmtD(x.d)}</div><div class="b">${esc(p?p.name:'Player')} ${p?`<span class="pos ${p.pos}">${p.pos}</span> OVR ${p.ovr}`:''}</div><div class="sm mut">Our offer ${money(x.fee)}${x.cfee?` · they want ${money(x.cfee)}`:''}${x.st==='pending'?` · answer by ${shortD(x.due)}`:''}</div>${x.msg?`<div class="sm">${esc(x.msg)}</div>`:''}</div><span class="chip ${x.st==='done'?'g':x.st==='pending'?'bl':x.st==='countered'?'y':'r'}">${({pending:'Pending',countered:'Counter-offer',done:'Signed',rejected:'Rejected',terms:'Player said no',failed:'Failed',withdrawn:'Withdrawn'})[x.st]}</span></div>${x.st==='countered'?`<div class="row wrap" style="margin-top:10px"><button class="btn grn sm" data-a="outpay:${x.id}">Pay ${money(x.cfee)}</button><button class="btn sm" data-a="outwd:${x.id}">Withdraw</button></div>`:''}${x.st==='pending'?`<button class="btn sm" style="margin-top:10px" data-a="outwd:${x.id}">Withdraw</button>`:''}</div>`}).join(''):'<div class="card empty">You haven\'t made any offers. Open a player and press Make offer.</div>'}
function trHist2(){return `<div class="card">${S.tr.hist.length?`<table><tr><th class="cl">Date</th><th class="cl">Deal</th><th>Fee</th></tr>${S.tr.hist.map(h=>`<tr><td class="cl sm">${fmtD(h.d)}</td><td class="cl">${h.dir==='in'?'⬇️':'⬆️'} ${esc(h.txt)}</td><td style="color:${h.dir==='in'?'var(--red2)':'var(--grn)'}">${money(h.fee)}</td></tr>`).join('')}</table>`:'<div class="empty">No deals yet.</div>'}</div>`}

P.more=()=>{const it=[['league','League','Tables, fixtures, results','more'],['club','Club history','Trophies, legends, points every season','cup'],['staff','Staff','Coach trust, board, dressing room','staff'],['board','Boardroom','Fans, reputation, crest, actions','home'],['academy','Academy','Youth prospects and intake','squad'],['fac','Facilities','Stadium, development, commercial','bolt'],['lab','Lab','Fuse skills between players','flask'],['awards','Awards','Monthly and season awards','star'],['store','Store','Unlocks, money and seeds','key'],['fin','Finances','Income, wages, transfers','coin'],['enc','Encyclopedia','How everything works','book'],['settings','Save and settings','Back up, restore, new game','mail']];
  return `<h1 style="margin-bottom:12px">More</h1><div class="grid2">${it.map(([k,t,d,ic])=>`<button class="card" style="text-align:left;margin:0;cursor:pointer" data-a="go:${k}"><div style="color:var(--red2)">${icon(ic)}</div><div class="b" style="font-size:18px;margin-top:6px">${t}</div><div class="sm mut">${d}</div></button>`).join('')}</div>`};
P.league=()=>{const lg=S.ui.lt!=null&&LEAGUES[S.ui.lt]?+S.ui.lt:me().lg;const L=LEAGUES[lg];const tb=table(lg);const maxR=(L.size-1)*2;const rnd=S.ui.lr||Math.max(1,(S.fx.filter(f=>f.lg===lg&&f.hs!==null).map(f=>f.r).sort((a,b)=>b-a)[0])||1);const fx=S.fx.filter(f=>f.lg===lg&&f.r===rnd);
  const ovs={};tb.forEach(r=>ovs[r.c]=avgOvr(r.c));const avg=Math.round(Object.values(ovs).reduce((a,b)=>a+b,0)/tb.length);const en=L.nat==='en';
  return `<div class="row" style="margin-bottom:12px">${back()}<h1>Leagues</h1></div><div class="tabs">${Object.keys(NATS).map(n=>`<button class="${L.nat===n?'on':''}" data-a="lnat:${n}">${NATS[n]}</button>`).join('')}</div>${en?`<div style="margin-bottom:8px">${LEAGUES.map((x,i)=>x.nat==='en'?`<button class="pill ${lg===i?'on':''}" data-a="lt:${i}">${x.tier}. ${x.n}</button>`:'').join('')}</div>`:''}
  <div class="card scroll"><div class="row" style="margin-bottom:6px"><h3>${L.n}</h3><span class="sp sm mut">${L.size} clubs · avg OVR ${avg}</span></div><table><tr><th>#</th><th class="cl">Club</th><th>OVR</th><th>P</th><th>W</th><th>D</th><th>L</th><th>GD</th><th>Pts</th></tr>${tb.map((r,i)=>`<tr class="${r.c===S.me.cid?'me':''} ${en&&L.tier>1&&i<3?'up':''} ${en&&L.tier<5&&i>=tb.length-3?'dn':''}" data-a="clubview:${r.c}" style="cursor:pointer"><td>${i+1}</td><td class="cl"><span class="row" style="gap:6px">${crest(S.clubs[r.c],18)}${esc(S.clubs[r.c].name)}</span><span class="note">${statusOf(S.clubs[r.c])[0]}</span></td><td>${ovs[r.c]}</td><td>${r.p}</td><td>${r.w}</td><td>${r.d}</td><td>${r.l}</td><td>${r.gf-r.ga}</td><td class="b">${r.pts}</td></tr>`).join('')}</table><p class="note">${en?'Top 3 promoted, bottom 3 relegated (English pyramid).':'Single top division: no promotion or relegation.'} Tap a club for its history.</p></div>
  <div class="card"><div class="row"><button class="btn sm" data-a="lr:${Math.max(1,rnd-1)}" aria-label="Previous round">‹</button><h3 style="flex:1;text-align:center">Round ${rnd}/${maxR} · ${fx[0]?shortD(fx[0].d):''}</h3><button class="btn sm" data-a="lr:${Math.min(maxR,rnd+1)}" aria-label="Next round">›</button></div>${fx.map(f=>`<div class="row" style="padding:8px 0;border-top:1px solid var(--line)"><span style="flex:1;text-align:right" class="${f.h===S.me.cid?'b':''}">${esc(S.clubs[f.h].name)}</span><span class="chip" style="min-width:54px;justify-content:center">${f.hs===null?'v':`${f.hs} - ${f.as}`}</span><span style="flex:1" class="${f.a===S.me.cid?'b':''}">${esc(S.clubs[f.a].name)}</span></div>`).join('')}</div>`};
P.club=()=>{const c=S.clubs[S.ui.cv||S.me.cid];const mine=c.id===S.me.cid;
  const ap={};sqAll(c.id).concat(Object.values(S.P).filter(p=>p.club!==c.id&&p.ca[c.id])).forEach(p=>{const x=p.ca[c.id];if(x)ap['p'+p.id]={name:p.name,pos:p.pos,apps:x[0],g:x[1],as:x[2],cur:p.club===c.id,aw:p.aw.length}});
  if(mine)S.retired.forEach((r,i)=>ap['r'+i]={name:r.name,pos:r.pos,apps:r.apps,g:r.g,as:r.as,ret:r.ret,aw:(r.aw||[]).length});
  const all=Object.values(ap);const leg=all.slice().sort((a,b)=>b.apps-a.apps).slice(0,10);const scs=all.slice().sort((a,b)=>b.g-a.g).filter(x=>x.g>0).slice(0,8);
  const tr={};c.troph.forEach(x=>{(tr[x.n]||(tr[x.n]=[])).push(x.s)});const rb=S.rec[c.id];const best=c.hist.slice().sort((a,b)=>LEAGUES[b.lg].q-LEAGUES[a.lg].q||a.pos-b.pos)[0];const gem=sqAll(c.id).find(p=>p.gem);
  return `<div class="row" style="margin-bottom:12px">${back(mine?'more':'league')}</div><div class="hero" style="background:${c.col}"><div class="row">${crest(c,64)}<div><div class="lbl">${lgName(c)} · ${NATS[c.nat]} · founded ${c.founded}</div><h1>${esc(c.name)}</h1><div style="margin:4px 0"><span class="chip ${statusOf(c)[1]}">${statusOf(c)[0]}</span></div><div class="sm" style="opacity:.9">${esc(c.ground)} · ${c.cap.toLocaleString()} seats · reputation ${Math.round(c.rep)}</div></div></div></div>
  ${gem&&!mine?`<div class="card flat sm">💎 Scouts whisper about a gem here: a young ${gem.pos} with a huge ceiling.</div>`:''}
  <div class="card"><h3>Trophy cabinet</h3>${Object.keys(tr).length?`<div class="cab" style="margin-top:10px">${Object.entries(tr).map(([n,ss])=>`<div class="cup">${icon('cup',38)}<div class="big" style="font-size:28px">${ss.length}×</div><div class="sm b">${esc(n)}</div><div class="note">${ss.map(seasonLbl).join(', ')}</div></div>`).join('')}</div>`:'<div class="empty">The cabinet is empty. For now.</div>'}<p class="sm mut" style="margin-bottom:0">Best finish: ${best?`${ord(best.pos)} in the ${LEAGUES[best.lg].n} (${seasonLbl(best.s)})`:'—'}${rb&&rb.win?` · Biggest win: ${esc(rb.win.txt)}`:''}</p></div>
  <div class="card scroll"><h3>Season by season</h3>${c.hist.length?`<table><tr><th class="cl">Season</th><th class="cl">Division</th><th>Pos</th><th>W-D-L</th><th>GD</th><th>Pts</th></tr>${c.hist.slice().reverse().map(h=>`<tr><td>${seasonLbl(h.s)}</td><td class="cl">${LEAGUES[h.lg].n}</td><td class="b">${ord(h.pos)}</td><td>${h.w}-${h.d}-${h.l}</td><td>${h.gf-h.ga}</td><td class="b">${h.pts}</td></tr>`).join('')}</table>`:'<div class="empty">The first season is still being written.</div>'}</div>
  <div class="card"><h3>Club legends · most appearances</h3>${leg.length?`<table><tr><th class="cl">Player</th><th>Apps</th><th>Goals</th><th>Ast</th></tr>${leg.map(x=>`<tr><td class="cl">${esc(x.name)} <span class="pos ${x.pos}">${x.pos}</span>${x.ret?` <span class="chip">retired ${seasonLbl(x.ret)}</span>`:x.cur?'':' <span class="chip">left</span>'}${x.aw?` <span class="chip y">${x.aw} awards</span>`:''}</td><td class="b">${x.apps}</td><td>${x.g}</td><td>${x.as}</td></tr>`).join('')}</table>`:'<div class="empty">No appearances yet.</div>'}</div>
  <div class="card"><h3>All-time top scorers</h3>${scs.length?`<table>${scs.map((x,i)=>`<tr><td>${i+1}</td><td class="cl">${esc(x.name)}</td><td class="b">${x.g} goals</td></tr>`).join('')}</table>`:'<div class="empty">No goals yet.</div>'}</div>
  ${mine&&S.me.log.length?`<div class="card"><h3>Manager's log</h3>${S.me.log.slice(-15).reverse().map(l=>`<div class="sm" style="padding:5px 0;border-top:1px solid var(--line)"><span class="mut">${fmtD(l.d)}</span> · ${esc(l.txt)}</div>`).join('')}</div>`:''}
  ${S.seasons.length?`<div class="card scroll"><h3>Champions archive</h3><table><tr><th class="cl">Season</th>${LEAGUES.map(l=>`<th class="cl">${l.n}</th>`).join('')}<th class="cl">Golden Orb</th></tr>${S.seasons.slice().reverse().map(s=>`<tr><td>${seasonLbl(s.s)}</td>${s.lgs.map(t=>`<td class="cl ${t.champ===S.me.cid?'b':''}">${esc(t.champName)}</td>`).join('')}<td class="cl">${esc(s.orb[0]?.name||'—')}</td></tr>`).join('')}</table></div>`:''}`};
P.staff=()=>{const co=coachOf(S.me.cid);const[ts,tk]=trustState(),[bs,bk]=boardState(),[ls,lk,lm]=leadState();const L=leaders();
  return `<div class="row" style="margin-bottom:12px">${back()}<h1>Staff</h1></div>${tabs('staff',[['coach','Coach'],['board','Board'],['room','Dressing room']])}`+({
  coach:()=>`<div class="card"><div class="row"><div><div class="lbl">${esc(co?.name||'No coach')} · trust in you</div><h2 style="color:var(--${tk==='g'?'grn':tk==='y'?'gold':'red2'})">${ts}</h2></div><span class="sp big">${Math.round(S.me.trust)}</span></div><div class="bar" style="margin:8px 0"><i style="width:${S.me.trust}%"></i></div><div class="row sm mut"><span>Broken</span><span style="margin:auto">Strained</span><span>Strong</span></div></div>
   <div class="card"><h3>What it does</h3><p class="sm">Above 75: tactical impact +10% and young players grow 10% faster. 35–75: normal. Below 35: his tactical impact is halved, the squad's morale slips every week and he warns you. Below 15 he resigns${boss()?' (Final Say keeps him at the club)':''}.</p><p class="sm">Trust rises when you sign the positions he asked for, sell the players he wants gone, act on his requests and win. It drops when you sign players he didn't want, sell his starters, force players into his team or ignore his requests.</p></div>
   <div class="card"><h3>Recent</h3>${S.me.tlog.length?S.me.tlog.map(l=>`<div class="row sm" style="padding:5px 0;border-top:1px solid var(--line)"><span class="mut">${fmtD(l.d)}</span><span style="flex:1">${esc(l.why)}</span><b style="color:${l.v>=0?'var(--grn)':'var(--red2)'}">${l.v>0?'+':''}${Math.round(l.v)}</b></div>`).join(''):'<div class="empty">Nothing yet.</div>'}</div>`,
  board:()=>`<div class="card"><div class="row"><div><div class="lbl">Board confidence</div><h2>${bs}</h2></div><span class="sp big">${Math.round(S.me.board)}</span></div><div class="bar" style="margin:8px 0"><i style="width:${S.me.board}%"></i></div></div><div class="card"><h3>What it does</h3><p class="sm">The board judges you every month against the target (${expectation().txt.toLowerCase()}). Being above target, a full stadium and money in the bank raise confidence. Below 25, sponsors get nervous and commercial income drops 15%${boss()?' (Final Say shields you from this)':''}. A season that hits the target gives +10; missing it costs 12.</p></div>`,
  room:()=>`<div class="card"><div class="row"><div><div class="lbl">Dressing-room leaders</div><h2>${ls}</h2></div><span class="sp big">${Math.round(lm)}</span></div><p class="sm mut">The three most senior, strongest players set the mood. Happy leaders lift everyone's morale each week; unhappy leaders drag it down.</p>${L.map(p=>prow(p)).join('')}</div>`})[tab('staff','coach')]()};
P.board=()=>{const c=me();const ex=expectation();const fl=c.fans>=75?'Behind you':c.fans>=55?'With you':c.fans>=35?'Restless':'Revolt';const fe=[300e3,120e3,40e3,15e3,6e3][c.t-1];const t=tab('board','fans');
  return `<div class="row" style="margin-bottom:12px">${back()}<h1>Boardroom</h1></div>${tabs('board',[['fans','Fans'],['club','Club'],['actions','Actions']])}`+({
  fans:()=>`<div class="card"><div class="row"><span class="lbl">The fans · your lifeline</span><span class="sp chip g">${Math.round(c.fans)} / 100</span></div><h1 style="color:var(--grn);margin:8px 0">${fl}</h1><div class="bar"><i style="width:${c.fans}%"></i></div><div class="row sm mut" style="margin-top:6px"><span>Revolt</span><span style="margin:auto">Restless</span><span>Behind you</span></div></div><div class="card"><div class="lbl">The board's expectation</div><h2 style="margin:6px 0 12px">${ex.txt}</h2><div class="grid2"><div><div class="lbl">Target</div><div class="b">${ord(ex.tgt)} or better</div></div><div><div class="lbl">Now</div><div class="b">${myPos()?ord(myPos()):'–'}</div></div></div></div>`,
  club:()=>`<div class="card"><div class="row"><span class="lbl">Club reputation</span><span class="sp chip g">${Math.round(c.rep)} / 100</span></div><p class="sm mut">Reputation decides who wants to sign, which sponsors call and how much commercial deals bring in.</p><div class="bar"><i style="width:${c.rep}%"></i></div></div><div class="card"><div class="lbl">Club identity</div><label class="f" style="margin-top:8px"><span>Club name</span><input type="text" id="rnClub" value="${esc(c.name)}" maxlength="32"></label><label class="f"><span>Ground</span><input type="text" id="rnGround" value="${esc(c.ground)}" maxlength="32"></label><button class="btn grn" data-a="rename">Save name and ground</button></div>${crestDesigner()}`,
  actions:()=>`<div class="card"><h3>Win bonus scheme</h3>${Object.entries(BONUS).map(([k,b])=>`<button class="li" data-a="bonus:${k}"><span style="flex:1"><span class="b">${k}</span><br><span class="sm mut">${b.d} ${money(b.cost*(6-c.t))} per win.</span></span>${S.me.bonus===k?'<span class="chip g">Active</span>':''}</button>`).join('')}</div>
  <div class="card"><h3>Your levers</h3>
  <div class="li" style="cursor:default"><span style="flex:1"><span class="b">Organise a fan event</span><br><span class="sm mut">A day at the ground for the supporters.</span><br><span class="chip y">Fans +8</span></span><button class="btn sm" data-a="lever:event">${money(fe)}</button></div>
  <div class="li" style="cursor:default"><span style="flex:1"><span class="b">Open training session</span><br><span class="sm mut">Invite fans and press to watch.</span><br><span class="chip bl">Morale +3</span></span><button class="btn sm" data-a="lever:open">€5K</button></div>
  <div class="li" style="cursor:default"><span style="flex:1"><span class="b">Visit training</span><br><span class="sm mut">The effect depends on recent form.</span><br><span class="chip">Morale ±</span></span><button class="btn sm" data-a="lever:visit">Free</button></div></div>`})[t]()};
function crestDesigner(){const c=me();const d=S.ui.cd||(S.ui.cd={...c.cr,ini:c.short});
  const pills=(key,obj)=>Object.keys(obj).map(k=>`<button class="pill ${d[key]===k?'on':''}" data-a="cd:${key}:${k}">${k}</button>`).join('');
  return `<div class="card"><h3>Crest designer</h3><p class="sm mut">Design an original badge for your club.</p>
  <div class="row" style="justify-content:center;gap:24px;margin:10px 0 14px;flex-wrap:wrap"><div style="text-align:center">${crestSVG(d,d.ini||c.short,110)}<div class="sm mut">Preview</div></div><div style="text-align:center">${crestSVG(c.cr,c.short,60)}<div class="sm mut">Current</div></div></div>
  <div class="lbl">Shape</div><div>${pills('sh',SHP)}</div><div class="lbl">Pattern</div><div>${pills('pt',PAT)}</div>
  <div class="lbl">Emblem</div><div>${Object.keys(ICO).map(k=>`<button class="pill ${d.ic===k?'on':''}" data-a="cd:ic:${k}" style="padding:2px 6px">${k==='none'?'none':`<svg viewBox="0 8 40 18" width="40" height="18" style="vertical-align:middle;background:#5a6b75;border-radius:4px"><g fill="#fff">${ICO[k]}</g></svg>`}</button>`).join('')}</div>
  <div class="grid3" style="margin-top:6px"><label class="f"><span>Main colour</span><input type="color" id="cdc1" value="${d.c1}" style="width:100%;height:44px;border:0;background:none;padding:0"></label><label class="f"><span>Second colour</span><input type="color" id="cdc2" value="${d.c2}" style="width:100%;height:44px;border:0;background:none;padding:0"></label><label class="f"><span>Letters</span><input type="text" id="cdini" value="${esc(d.ini||c.short)}" maxlength="3"></label></div>
  <label class="row" style="margin-bottom:12px;min-height:44px"><input type="checkbox" id="cdband" ${d.band?'checked':''} style="width:22px;height:22px"> <span>Dark band behind the letters</span></label>
  <div class="row wrap"><button class="btn grn" data-a="cdsave">Save crest</button><button class="btn" data-a="cdrand">🎲 Surprise me</button><button class="btn ghost" data-a="cdreset">Undo changes</button></div></div>`}
P.academy=()=>{const ys=youth(S.me.cid).sort((a,b)=>b.pot-a.pot);const lvl=S.me.fac.ac;const o=dobj(S.d);const next=o.m>=3?`1 Apr ${o.y+1}`:`1 Apr ${o.y}`;
  return `<div class="row" style="margin-bottom:12px">${back()}<h1>Academy</h1></div><div class="grid3" style="margin-bottom:14px"><div class="card" style="margin:0"><div class="lbl">Academy</div><div class="big">${Math.min(lvl,20)}/20</div><div class="sm b" style="color:var(--gold)">${lvl>20?esc(ACADN(lvl)):''}</div></div><div class="card" style="margin:0"><div class="lbl">Next intake</div><div class="b">${next}</div><div class="sm mut">${intakeN(lvl)} players</div></div><div class="card" style="margin:0"><div class="lbl">Network</div><div class="big">${S.me.fac.sc}/5</div></div></div>
  <div class="card"><h3>Academy squad</h3>${ys.length?ys.map(p=>`<div class="row" style="border-bottom:1px solid var(--line)">${prow(p)}<span class="sm mut">pot ${S.me.unl.eyes?p.pot:'~'+Math.round(p.pot/5)*5}</span><button class="btn sm grn" data-a="promote:${p.id}">Promote</button></div>`).join(''):'<div class="empty">No youngsters yet. The intake arrives every April. Wonderkid Drop in the Store adds some now.</div>'}</div>`};
const FAC=[['tr','Training ground','How fast players grow toward their potential',20],['ac','Youth academy','Size and quality of every April intake',22],['md','Medical centre','Fewer injuries',20],['sc','Scouting network','Better reports and agency names',5]];
const facCost=(k,l)=>k==='sc'?[0,250e3,900e3,2.5e6,6e6][l]||0:k==='ac'&&l>=20?[25e6,80e6][l-20]:Math.round(60e3*Math.pow(1.33,l)/1e4)*1e4;
function stadiumSVG(l,col){const W=360,H=200;const tiers=1+Math.floor(l/5);const roof=l>=6,lights=l>=3,screen=l>=10,bowl=l>=15,arch=l>=20;const sc=Math.min(1,.55+l*.025);
  const pw=150*sc+40,ph=80*sc+18;const cx=W/2,cy=H/2+12;let s=`<svg viewBox="0 0 ${W} ${H}" style="width:100%;display:block;border-radius:14px" role="img" aria-label="Stadium, level ${l}"><rect width="${W}" height="${H}" fill="#9cc49a"/>`;
  if(l<8)for(let i=0;i<14;i++){const x=(i*53)%W,y=i%2?16:H-18;s+=`<circle cx="${x+10}" cy="${y}" r="${7+(i%3)*2}" fill="#5f9a5c"/>`}
  if(l<12)s+=`<rect x="8" y="${H-46}" width="60" height="34" rx="4" fill="#b9b6aa"/>${[0,1,2,3].map(i=>`<rect x="${14+i*13}" y="${H-40}" width="8" height="5" fill="${['#c8321e','#1e5fb4','#f1c84b','#16804a'][i]}"/>`).join('')}`;
  for(let t=tiers;t>=1;t--){const pad=t*14*sc+4;const rx=cx-pw/2-pad,ry=cy-ph/2-pad,rw=pw+pad*2,rh=ph+pad*2;s+=`<rect x="${rx}" y="${ry}" width="${rw}" height="${rh}" rx="${bowl?rh/2.4:8}" fill="${t%2?'#6c7176':'#80868b'}"/>`;for(let k=0;k<rw;k+=7)s+=`<rect x="${rx+k}" y="${ry+2}" width="4" height="${Math.max(3,pad-16*sc)}" fill="${col}" opacity=".85"/><rect x="${rx+k}" y="${ry+rh-2-Math.max(3,pad-16*sc)}" width="4" height="${Math.max(3,pad-16*sc)}" fill="${col}" opacity=".85"/>`}
  if(!bowl)s+=`<rect x="${cx-pw/2-tiers*14*sc-4}" y="${cy-ph/2-tiers*14*sc-4}" width="12" height="12" fill="#9cc49a"/><rect x="${cx+pw/2+tiers*14*sc-8}" y="${cy-ph/2-tiers*14*sc-4}" width="12" height="12" fill="#9cc49a"/>`;
  s+=`<rect x="${cx-pw/2}" y="${cy-ph/2}" width="${pw}" height="${ph}" fill="#3f8a4c"/>${[0,1,2,3,4,5].map(i=>i%2?`<rect x="${cx-pw/2+i*pw/6}" y="${cy-ph/2}" width="${pw/6}" height="${ph}" fill="#479653"/>`:'').join('')}<g fill="none" stroke="#fff" stroke-opacity=".8" stroke-width="1"><rect x="${cx-pw/2+3}" y="${cy-ph/2+3}" width="${pw-6}" height="${ph-6}"/><line x1="${cx}" y1="${cy-ph/2+3}" x2="${cx}" y2="${cy+ph/2-3}"/><circle cx="${cx}" cy="${cy}" r="${ph*.14}"/></g>`;
  if(roof)s+=`<rect x="${cx-pw/2-tiers*14*sc-4}" y="${cy-ph/2-tiers*14*sc-10}" width="${pw+tiers*28*sc+8}" height="10" fill="#3a3f44" opacity=".85" rx="3"/>`;
  if(lights)[[-1,-1],[1,-1],[-1,1],[1,1]].forEach(([a,b])=>{const x=cx+a*(pw/2+tiers*14*sc+10),y=cy+b*(ph/2+tiers*14*sc+8);s+=`<line x1="${x}" y1="${y}" x2="${x}" y2="${y-26}" stroke="#4a4f54" stroke-width="2.5"/><rect x="${x-7}" y="${y-34}" width="14" height="9" fill="#fff6c2" stroke="#4a4f54"/>`});
  if(screen)s+=`<rect x="${cx+pw/2+4}" y="${cy-12}" width="14" height="24" fill="#17191a"/><rect x="${cx+pw/2+6}" y="${cy-10}" width="10" height="20" fill="#3d8bfd"/>`;
  if(arch)s+=`<path d="M${cx-pw/2-50} ${cy+ph/2+30} Q ${cx} ${cy-ph-60} ${cx+pw/2+50} ${cy+ph/2+30}" fill="none" stroke="#e8e3d4" stroke-width="5"/>`;
  return s+`</svg>`}
P.fac=()=>{const t=tab('fac','stadium');return `<div class="row" style="margin-bottom:12px">${back()}<h1>Facilities</h1><span class="sp b" style="color:var(--grn)">${money(S.me.money)}</span></div>${tabs('fac',[['stadium','Stadium'],['dev','Development'],['com','Commercial']])}${({stadium:facStadium,dev:facDev,com:facCom})[t]()}`};
function facStadium(){const c=me();const l=S.me.fac.st,cost=S.me.unl.builders?0:Math.round(facCost('st',l)*1.5/1e4)*1e4;const ea=expAtt();const cond=Math.round(S.me.pitch.c);const cs=cond>=85?['Perfect','g']:cond>=60?['Good','bl']:cond>=40?['Worn','y']:['Ruined','r'];
  return `<div class="card"><div class="row" style="margin-bottom:8px"><div><div class="lbl">${esc(c.ground)}</div><h2>${c.cap.toLocaleString()} seats</h2></div><span class="sp big">${l}<span class="mut" style="font-size:18px"> / 20</span></span></div>${stadiumSVG(l,c.col)}<p class="note">The stadium grows as you upgrade: floodlights at 3, a roof at 6, a second deck at 8, a big screen at 10, a full bowl at 15 and an iconic arch at 20.</p>${l<20?`<button class="btn grn" data-a="upg:st">Expand · ${cost?money(cost):'Free'}</button>`:'<span class="chip g">Fully built</span>'}</div>
  <div class="card"><h3>Matchday</h3><div class="grid3"><div><div class="lbl">Expected crowd</div><div class="big" style="font-size:26px">${ea.toLocaleString()}</div><div class="sm mut">${Math.round(ea/c.cap*100)}% full</div></div><div><div class="lbl">Ticket</div><div class="row"><button class="btn sm" data-a="ticket:-1" aria-label="Lower price">−</button><b>€${S.me.ticket}</b><button class="btn sm" data-a="ticket:1" aria-label="Raise price">+</button></div><div class="sm mut">fair price €${FAIRT[c.t-1]}</div></div><div><div class="lbl">Gate per game</div><div class="b">${money(ea*S.me.ticket*(1+(5-c.t)*.4))}</div></div></div><p class="note">Crowds follow fans, reputation, recent form, ticket price and the state of the pitch.</p></div>
  <div class="card"><div class="row"><h3>Pitch</h3><span class="sp chip ${cs[1]}">${cs[0]} · ${cond}%</span></div><div class="bar" style="margin:8px 0"><i style="width:${cond}%"></i></div>${Object.entries(PLANS).map(([k,p])=>`<button class="li" data-a="plan:${k}"><span style="flex:1"><span class="b">${k}</span> <span class="sm mut">${money(p.cost[c.t-1])}/month</span><br><span class="sm mut">${p.d}</span></span>${S.me.pitch.plan===k?'<span class="chip g">Active</span>':''}</button>`).join('')}<p class="note">Every home game wears the grass. Above 85%: +1 home advantage. Below 60%: home advantage drops. Below 40%: injuries at home go up 60%, fans lose patience and crowds shrink. Below 20%: injuries more than double.</p></div>`}
function facDev(){return FAC.map(([k,n,d,mx])=>{const l=S.me.fac[k],cost=S.me.unl.builders?0:facCost(k,l);const eff={tr:`About +${(1.6+l*.22).toFixed(1)} OVR a year for a young player below potential`,ac:`${intakeN(l)} players per intake${l>=20?` · ${ACADN(l)}`:''}`,md:`Injury risk −${Math.round(l*3.5)}%`,sc:`Reports +${l} OVR · ${money([15e3,40e3,90e3,180e3,350e3][l-1])}/month`}[k];const nextN=k==='ac'&&l>=20&&l<22?` → ${ACADN(l+1)} (+${l===20?5:10} intake)`:'';
  return `<div class="card"><div class="row"><div><h3>${n}</h3><div class="sm mut">${d}</div></div><span class="sp big">${Math.min(l,mx===22?20:mx)}<span class="mut" style="font-size:18px"> / ${mx===22?20:mx}</span></span></div>${k==='ac'&&l>20?`<div class="chip y" style="margin-top:6px">${esc(ACADN(l))}</div>`:''}<div class="bar" style="margin:10px 0"><i style="width:${Math.min(100,l/(mx===22?20:mx)*100)}%"></i></div><div class="row wrap"><span class="sm">${eff}${nextN}</span>${l<mx?`<button class="btn grn sm sp" data-a="upg:${k}">${k==='ac'&&l>=20?'Unlock':'Upgrade'} · ${cost?money(cost):'Free'}</button>`:'<span class="chip g sp">Maxed</span>'}</div></div>`}).join('')}
function facCom(){const c=me();const com=S.me.com;const row=(k,n,d,inc)=>{const l=com[k];const cost=S.me.unl.builders?0:comCost(k,l);return `<div class="card"><div class="row"><div><h3>${n}</h3><div class="sm mut">${d}</div></div><span class="sp big">${l}<span class="mut" style="font-size:18px"> / 10</span></span></div><div class="row wrap" style="margin-top:8px"><span class="sm">${inc}</span>${l<10?`<button class="btn grn sm sp" data-a="com:${k}">Upgrade · ${cost?money(cost):'Free'}</button>`:'<span class="chip g sp">Maxed</span>'}</div></div>`};const no=namingOffer();
  return `<div class="card flat sm">Commercial income keeps a free-to-play club alive. It grows slowly; the Store tops it up instantly.</div>
  ${row('shop','Club shop','Shirts, scarves and Lophus plushies. Paid monthly, grows with fans.',`≈ ${money(shopInc())}/month`)}
  ${row('cat','Catering','Pies and drinks on matchday.',`≈ ${money(Math.round(expAtt()*.6*com.cat))} per home game`)}
  ${row('hosp','Hospitality boxes','Corporate guests on matchday.',`≈ ${money(com.hosp*4*300*TMULT[c.t-1])} per home game`)}
  <div class="card"><h3>Stadium naming rights</h3>${com.naming?`<p class="sm">${esc(c.ground)} · <b>${money(com.naming.amt)}/month</b> from ${esc(com.naming.sp)}.</p><button class="btn sm" data-a="naming:end">End the deal (fans +5)</button>`:c.rep>=45?`<p class="sm">${esc(com.nsp||(com.nsp=pick(['Kestrel','Halcyon','Tidewater','Borneo Brew','Pixel Peak','Northgate'])))} want to rename the ground for <b>${money(no)}/month</b>. Fans won't love it (−5).</p><button class="btn grn sm" data-a="naming:take">Sign the deal</button>`:'<p class="sm mut">Unlocks at reputation 45.</p>'}</div>
  <div class="card"><h3>Base commercial deals</h3><p class="sm">${money(Math.round(COMM[c.t-1]*(.6+c.rep/150)))}/month from shirt and league deals. Rises with division and reputation.</p></div>`}
P.lab=()=>{const my=sq(S.me.cid).concat(youth(S.me.cid));const sub=S.P[S.ui.lsub]||my[0];const donors=my.filter(p=>p!==sub&&p.tr.length);const don=S.P[S.ui.ldon]&&S.ui.ldon!=sub?.id?S.P[S.ui.ldon]:donors[0];const sid=don&&don.tr.includes(+S.ui.lsk)?+S.ui.lsk:don?.tr[0];const seeds=cl(+S.ui.lseed||10,1,Math.max(1,S.me.seeds));const copy=!!S.ui.lcopy;const t=sid!=null?tierOf(sid):8;const ch=sid!=null?fuseChance(t,seeds,copy):0;
  const card=(p,lbl)=>p?`<div class="card" style="margin:0;text-align:center"><div class="lbl">${lbl}</div><div class="num" style="margin:6px auto;background:${me().col};width:48px;height:48px;font-size:22px">${p.num||'–'}</div><div class="b">${esc(p.name)}</div><div class="sm mut">${p.pos} · OVR ${p.ovr}</div><div style="margin-top:6px">${p.tr.map(id=>skPill(id)).join(' ')||'<span class="note">no skills</span>'}</div></div>`:'<div class="card empty" style="margin:0">—</div>';
  return `<div class="row" style="margin-bottom:12px">${back()}<h1>Lab</h1><span class="sp b">🌱 ${S.me.seeds} seeds</span></div>
  <div class="card"><div class="grid2"><label class="f"><span>Subject (receives the skill)</span><select id="lsub">${my.map(p=>`<option value="${p.id}" ${p===sub?'selected':''}>${esc(p.name)} · ${p.pos} ${p.ovr}</option>`).join('')}</select></label><label class="f"><span>Donor (gives the skill)</span><select id="ldon">${donors.length?donors.map(p=>`<option value="${p.id}" ${p===don?'selected':''}>${esc(p.name)} · ${p.tr.length} skill${p.tr.length>1?'s':''}</option>`).join(''):'<option>No players with skills</option>'}</select></label></div>
  ${don?`<div class="lbl">Skill to move</div><div style="margin:6px 0 10px">${don.tr.map(id=>`<button class="tpill ${id===sid?'sel':''}" style="${tierStyle(tierOf(id))};border:0;cursor:pointer" data-a="lsk:${id}">${SK[id].act?'⚡ ':''}${esc(SK[id].n)}</button>`).join(' ')}</div>`:''}
  <label class="f"><span>Seeds to spend: <b id="lseedv">${seeds}</b></span><input type="range" id="lseed" min="1" max="${Math.max(1,S.me.seeds)}" value="${seeds}" style="width:100%"></label>
  <label class="row" style="min-height:44px"><input type="checkbox" id="lcopy" ${copy?'checked':''} style="width:22px;height:22px"><span>Copy instead of transfer (donor keeps it, chance halved)</span></label></div>
  ${sub&&don&&sid!=null?`<div class="card"><div class="lbl" style="margin-bottom:8px">Preview</div><div class="grid2">${card(don,'Donor')}${card(sub,'Subject')}</div><div style="text-align:center;margin-top:8px"><span style="font-size:22px">⬇</span> ${skPill(sid)} <span style="font-size:22px">➜</span></div>
   <div class="card flat" style="margin-top:12px"><div class="row"><div><div class="lbl">${TIERS[t].n} · Tier ${t+1}</div><div class="sm">${esc(fxText(SK[sid].fx))}${SK[sid].act?` · ⚡ ${esc(SK[sid].act.n)}: ${esc(SK[sid].act.d)} (${Math.round(SK[sid].act.ch*100)}% per match)`:''}</div></div><span class="sp big" style="color:${ch>=.6?'var(--grn)':ch>=.25?'var(--gold)':'var(--red2)'}">${Math.round(ch*100)}%</span></div><div class="bar" style="margin-top:8px"><i style="width:${ch*100}%"></i></div><p class="note">Each seed adds ${(SEEDP[t]*100).toFixed(2)}% to a ${TIERS[t].n} fusion. Higher tiers need far more seeds. Seeds are spent win or lose.${sub.tr.includes(sid)?' The subject already has this skill.':''}</p></div>
   <button class="btn pri wide" data-a="fuse" ${S.me.seeds<1||sub.tr.includes(sid)||sub.tr.length>=6?'disabled':''}>Fuse · ${seeds} seeds</button></div>`:'<div class="card empty">Pick a subject and a donor that has a skill.</div>'}
  <div class="card"><h3>Getting seeds</h3><p class="sm">+2 per win, +1 per draw, +10 for each monthly award one of ours wins, +25 at the end of every season. The Store tops up seeds for free.</p></div>`};
P.awards=()=>{const t=tab('aw','orb');return `<div class="row" style="margin-bottom:12px">${back()}<h1>Awards</h1></div>${tabs('aw',[['orb','Golden Orb'],['season','Seasons'],['month','Monthly']])}`+({
 orb:()=>S.seasons.length?S.seasons.slice().reverse().map(s=>{const w=s.orb[0];return `<div class="card"><div class="row"><div class="cup" style="padding:8px">${icon('star',30)}</div><div><div class="lbl">Golden Orb ${seasonLbl(s.s)}</div><h2>${esc(w?.name||'—')}</h2><div class="sm mut">${w?`${esc(w.clubName)} · ${esc(LEAGUES[w.lg].n)} · ${w.g} goals · ${w.as} assists · avg ${w.avg}`:''}</div></div></div><details style="margin-top:8px"><summary class="b" style="cursor:pointer;min-height:40px;display:flex;align-items:center">Top 10</summary><table>${s.orb.map((x,i)=>`<tr class="${x.club===S.me.cid?'me':''}"><td>${i+1}</td><td class="cl">${esc(x.name)} <span class="pos ${x.pos}">${x.pos}</span><br><span class="note">${esc(x.clubName)}</span></td><td>${x.g}g ${x.as}a</td><td class="b">${x.sc}</td></tr>`).join('')}</table></details></div>`}).join(''):`<div class="card"><h3>Golden Orb</h3><p class="sm">At the end of every season the best player across all six countries wins the Golden Orb. Votes weigh match ratings, goals and assists, the strength of his league and how his team finished. Defenders and keepers get a small boost. The first one is handed out on 1 July ${S.season+1}.</p></div>`,
 season:()=>S.seasons.length?S.seasons.slice().reverse().map(s=>`<div class="card"><h3>Season ${seasonLbl(s.s)}</h3>${s.lgs.map(t=>`<div class="sm" style="padding:6px 0;border-top:1px solid var(--line)"><b>${LEAGUES[t.lg].n}:</b> champions ${esc(t.champName)}${t.ts?` · Golden Boot ${esc(t.ts.name)} (${t.ts.g})`:''}${t.pots?` · Player of the Season ${esc(t.pots.name)}`:''}</div>`).join('')}</div>`).join(''):'<div class="card empty">Season awards arrive on 1 July.</div>',
 month:()=>`<div class="card">${S.aw.length?S.aw.map(a=>`<div style="padding:10px 0;border-top:1px solid var(--line)"><div class="lbl">${MON[a.m]} ${a.y} · ${LEAGUES[a.t]?.n||''}</div><div class="${a.potm.club===S.me.cid?'b':''}">🏅 Player: ${esc(a.potm.name)} <span class="mut sm">${esc(S.clubs[a.potm.club]?.name||'')} · ${a.potm.avg}</span></div>${a.ypotm?`<div class="${a.ypotm.club===S.me.cid?'b':''}">🌱 Young player: ${esc(a.ypotm.name)} <span class="mut sm">${esc(S.clubs[a.ypotm.club]?.name||'')}</span></div>`:''}<div class="${a.cotm.club===S.me.cid?'b':''}">📋 Coach: ${esc(a.cotm.name)} <span class="mut sm">${esc(S.clubs[a.cotm.club]?.name||'')} · ${a.cotm.pts} pts</span></div></div>`).join(''):'<div class="empty">The first awards are handed out at the start of September.</div>'}</div>`})[t]()};
P.fin=()=>`<div class="row" style="margin-bottom:12px">${back()}<h1>Finances</h1></div><div class="card"><div class="lbl">Available budget</div><div class="big" style="font-size:44px;color:${S.me.money<0?'var(--red2)':'var(--grn)'}">${money(S.me.money)}</div><div class="row wrap" style="margin-top:8px"><button class="btn sm" data-a="go:store">Top up in the Store</button><button class="btn sm" data-a="tabgo:fac:com">Grow commercial income</button></div></div><div class="card scroll"><h3>Monthly ledger</h3>${S.me.fin.hist.length?`<table><tr><th class="cl">Month</th><th>Commercial</th><th>Matchday</th><th>Total in</th><th>Out</th><th>Net</th></tr>${S.me.fin.hist.map(h=>`<tr><td>${MON[h.m]} ${h.y}</td><td>${money(h.com||0)}</td><td>${money(h.tk||0)}</td><td>${money(h.inc)}</td><td>${money(h.out)}</td><td class="b" style="color:${h.inc-h.out>=0?'var(--grn)':'var(--red2)'}">${money(h.inc-h.out)}</td></tr>`).join('')}</table>`:'<div class="empty">The first month closes on 1 August.</div>'}<p class="note">In: commercial deals, shop, naming rights, tickets, catering, hospitality, sponsors and sales. Out: wages, scouting network, pitch care, win bonuses and signings.</p></div>`;
const STORE=[['boss','Final Say','Coaches, players, rival clubs and the board accept every request you make. Nobody refuses the manager.','key','unlock'],['eyes',"Scout's Eye",'See every player\'s true potential, and agency briefs always hit the mark.','scout','unlock'],['editor','Player Editor','Change any player\'s attributes, caps, age, position, potential and skills.','squad','unlock'],['creator','Create a Player','Design your own player and drop him straight into the squad.','star','unlock'],['builders','Instant Builders','Every facility and commercial upgrade costs nothing.','bolt','unlock'],['fanlock','Fan Favourite','Fan support stays locked at 100.','home','unlock'],['wonder','Wonderkid Drop','Three 16–17-year-olds with 85+ potential join your academy now.','star','use'],['star','Marquee Signing','A brand-new 85–92 rated star in a position you pick signs for free.','cup','use'],['scroll','Skill Scroll','Roll a random skill (any tier, real odds) onto the player you pick.','flask','use'],['skip','Skip to Season End','Simulate every remaining match. Mail waits for you.','bolt','use']];
P.store=()=>{const my=sq(S.me.cid);return `<div class="row" style="margin-bottom:12px">${back()}<h1>Store</h1></div>
<div class="hero"><div class="lbl">Chairman's account · admin</div><h2>If you want it, you've got it</h2><p style="margin:6px 0 12px">You're the admin. Everything here is free.</p><div class="row wrap">${[1e6,1e7,1e8].map(v=>`<button class="btn" style="background:#fff;color:#17191a" data-a="topup:${v}">+${money(v)}</button>`).join('')}</div><div class="row" style="margin-top:10px"><input type="number" id="tuAmt" placeholder="Custom amount in €" style="background:#fff;color:#17191a"><button class="btn" style="background:#17191a;color:#fff" data-a="topupc">Add</button></div><div class="row wrap" style="margin-top:10px">${[100,1000,10000].map(v=>`<button class="btn" style="background:#fff;color:#17191a" data-a="seeds:${v}">+${v.toLocaleString()} 🌱 seeds</button>`).join('')}</div></div>
${STORE.map(([id,n,d,ic,ty])=>{const on=S.me.unl[id];const got=id in S.me.unl;return `<div class="card store-item"><span class="store-ic">${icon(ic)}</span><div style="flex:1"><div class="row"><span class="b" style="font-size:17px">${n}</span>${ty==='unlock'&&got?`<span class="chip ${on?'g':''}">${on?'On':'Off'}</span>`:''}</div><div class="sm mut">${d}</div>${id==='star'?`<select id="starPos" style="margin-top:8px;max-width:160px">${POSL.map(x=>`<option ${x==='ST'?'selected':''}>${x}</option>`).join('')}</select>`:''}${id==='scroll'?`<select id="scrollP" style="margin-top:8px">${my.map(p=>`<option value="${p.id}">${esc(p.name)} · ${p.pos} ${p.ovr}</option>`).join('')}</select>`:''}</div>${ty==='unlock'?(got?`<button class="toggle ${on?'on':''}" data-a="tog:${id}" aria-label="Toggle ${n}" aria-pressed="${!!on}"></button>`:`<button class="btn grn sm" data-a="unlock:${id}">Unlock · Free</button>`):`<button class="btn grn sm" data-a="use:${id}">Use · Free</button>`}</div>`}).join('')}
${S.me.unl.creator?creatorForm():''}`};
function creatorForm(){return `<div class="card" id="creator"><h3>Create a Player</h3><label class="f"><span>Name</span><div class="row"><input type="text" id="crName" value="${esc(pname())}" maxlength="30"><button class="btn sm" data-a="crRand" aria-label="Random name">🎲</button></div></label><div class="grid2"><label class="f"><span>Position</span><select id="crPos">${POSL.map(x=>`<option ${x==='ST'?'selected':''}>${x}</option>`).join('')}</select></label><label class="f"><span>Age</span><input type="number" id="crAge" value="19" min="15" max="40"></label><label class="f"><span>OVR</span><input type="number" id="crOvr" value="70" min="25" max="99"></label><label class="f"><span>Potential</span><input type="number" id="crPot" value="94" min="25" max="99"></label></div><label class="f"><span>Signature stat</span><select id="crEmph">${ATT.map(k=>`<option value="${k}">${ALF[k]}</option>`).join('')}</select></label><button class="btn pri wide" data-a="create">Create and sign</button></div>`}
P.settings=()=>`<div class="row" style="margin-bottom:12px">${back()}<h1>Save and settings</h1></div><div class="card"><h3>Autosave</h3><p class="sm mut">The game saves in this browser after every action. To move to another device, copy your save code and paste it there.</p><button class="btn grn" data-a="copysave">Copy save code</button></div><div class="card"><h3>Restore a save</h3><textarea id="imp" rows="4" placeholder="Paste a save code here"></textarea><button class="btn" style="margin-top:8px" data-a="importsave">Load this save</button></div><div class="card"><h3>Manager name</h3><div class="row"><input type="text" id="mgrName" value="${esc(S.me.name)}" maxlength="24"><button class="btn" data-a="mgrname">Save</button></div></div><div class="card"><h3>New game</h3><p class="sm mut">Starts a fresh world. Your current save will be replaced.</p>${S.ui.confirmNew?`<div class="row"><button class="btn" style="background:var(--red);color:#fff" data-a="newgame">Yes, start over</button><button class="btn" data-a="cancelnew">Cancel</button></div>`:`<button class="btn" data-a="asknew">Start a new game</button>`}</div>`;
P.enc=()=>{const cat=tab('enc','basics');const sec=ENC.find(c=>c[0]===cat)||ENC[0];const topic=tab('enc_'+cat,sec[2][0][0]);const tp=sec[2].find(t=>t[0]===topic)||sec[2][0];
  return `<div class="row" style="margin-bottom:12px">${back()}<h1>Encyclopedia</h1></div>${tabs('enc',ENC.map(c=>[c[0],c[1]]))}${subtabs('enc_'+cat,sec[2].map(t=>[t[0],t[1]]))}<div class="card enc">${typeof tp[2]==='function'?tp[2]():tp[2]}</div>`};

/* ---------- player sheet ---------- */
function playerSheet(id){const p=S.P[id];if(!p)return;const c=S.clubs[p.club];const mine=p.club===S.me.cid;const co=coachOf(S.me.cid);const tac=co?.tac;const showPot=S.me.unl.eyes||mine;const ed=S.me.unl.editor;const tf=traitFx(p);const cb=cboost(S.me.cid);
  const career=Object.entries(p.ca).map(([cid,x])=>`<tr><td class="cl">${esc(S.clubs[cid]?.name||'?')}</td><td>${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td></tr>`).join('');
  const L=mine?pickXI(S.me.cid):null;const starts=L&&L.xi.includes(p);const[il,ik]=intLbl(interest(p));
  const yrs=p.ovr<p.pot?Math.ceil((p.pot-p.ovr)/((1.6+(mine?S.me.fac.tr:(c?.fl?.tr||5))*.22)*(p.age<=23?1:.8)*(1+(tf.grow||0)/100))):0;
  modal(`<div class="row"><span class="num" style="width:52px;height:52px;font-size:24px;background:${c?c.col:'#777'}">${p.num||'–'}</span><div><h2>${p.gem?'💎 ':''}${esc(p.name)}</h2><div class="row sm mut" style="gap:6px;flex-wrap:wrap"><span class="pos ${p.pos}">${p.pos}</span>${p.age}y · ${NATN[p.nat]} · ${c?esc(c.name):'Free agent'}${p.yth?' · academy':''}</div></div><button class="btn sm sp" data-a="close" aria-label="Close">✕</button></div>
  <div class="grid4" style="margin:14px 0"><div class="prof top"><div class="lbl">OVR</div><div class="big">${p.ovr}</div></div><div class="prof"><div class="lbl">Fit</div><div class="big">${fitC(p)}</div></div><div class="prof"><div class="lbl">Potential</div><div class="big">${showPot?p.pot:'~'+Math.round(p.pot/5)*5}</div></div><div class="prof"><div class="lbl">Morale</div><div class="big" style="color:${moCol(p.mo)}">${Math.round(p.mo)}</div></div></div>
  ${p.gem?`<div class="card flat sm">💎 A club gem. Huge ceiling, raw today. ${yrs?`At this club's training level he needs roughly ${yrs} more season${yrs>1?'s':''} to reach it.`:''}</div>`:''}
  <div class="lbl">Stats <span class="note">base · cap · boost from style${cb?`, coach +${cb}`:''}${Object.keys(tf).some(k=>k in AL)?', skills':''}</span></div>
  ${ATT.map(k=>{const w=TAC[tac||'Total Football'][ATT.indexOf(k)];const tb=w>=35?2:w>=25?1:0;const sb=tf[k]||0;const tot=p[k]+tb+cb+sb;return `<div class="att"><span>${AL[k]}${k===p.sig?' ★':''}</span><div class="bar2"><i style="width:${p[k]}%"></i><b style="left:${Math.min(99,showPot?p.cap[k]:p[k])}%" title="cap"></b></div><span class="b">${p[k]}<span class="note">${showPot?`/${p.cap[k]}`:''}${tb+cb+sb?` <span style="color:var(--grn)">+${tb+cb+sb}</span>`:''}</span></span></div>`}).join('')}
  ${p.tr.length?`<div class="lbl" style="margin-top:10px">Skills</div>${p.tr.slice().sort((a,b)=>tierOf(a)-tierOf(b)).map(id=>{const s=SK[id];return s?`<div style="padding:6px 0;border-top:1px solid var(--line)">${skPill(id)} <span class="note">${TIERS[s.t].n} · Tier ${s.t+1}</span><div class="sm">${esc(fxText(s.fx))}${s.act?`<br>⚡ <b>${esc(s.act.n)}</b>: ${esc(s.act.d)} · ${Math.round(s.act.ch*100)}% chance each match`:''}</div></div>`:''}).join('')}`:''}
  <div class="grid3" style="margin:12px 0"><div><div class="lbl">Value</div><div class="b">${money(p.val)}</div></div><div><div class="lbl">Wage</div><div class="b">${money(p.wage)}/mo</div></div><div><div class="lbl">Season</div><div class="b">${p.sA} apps · ${p.sG} g · ${p.sAs} a${p.sY?` · ${p.sY}🟨`:''}${p.sRd?` · ${p.sRd}🟥`:''}</div></div></div>
  ${p.inj>0?`<div class="chip r" style="margin-bottom:10px">Injured · ${p.inj} days</div>`:''}${p.ban>0?`<div class="chip r" style="margin-bottom:10px">Suspended next match</div>`:''}
  ${p.aw.length?`<div class="card flat"><div class="lbl">Honours</div>${p.aw.map(a=>`<div class="sm">🏅 ${esc(a)}</div>`).join('')}</div>`:''}
  ${career?`<div class="card flat scroll"><div class="lbl">Career</div><table><tr><th class="cl">Club</th><th>Apps</th><th>G</th><th>A</th></tr>${career}</table></div>`:''}
  ${!mine?`<div class="row" style="margin-bottom:6px"><span class="lbl">Interest in joining you</span><span class="chip ${ik}">${boss()?'Final Say: he will join':il}</span></div>`:''}
  <div id="pmsg"></div>
  ${mine?`<div class="row wrap" style="margin-top:10px">${p.yth?`<button class="btn grn" data-a="promote:${p.id}">Promote to first team</button>`:`${S.me.force.includes(p.id)?`<button class="btn" data-a="unforce:${p.id}">Let coach decide</button>`:`<button class="btn grn" data-a="force:${p.id}">${starts?'Keep him starting':'Ask coach to start him'}</button>`}<button class="btn" data-a="sell:${p.id}">Put up for sale</button><button class="btn" data-a="release:${p.id}">Release</button>`}</div>`
  :p.club?`<div class="row wrap" style="margin-top:10px"><input type="number" id="offAmt" value="${Math.round(p.val/1000)}" style="max-width:140px" aria-label="Offer in thousands of euros"><span class="sm mut">€K</span><button class="btn grn" data-a="offer:${p.id}">Make offer</button><button class="btn" data-a="shortp:${p.id}">${S.me.short.includes(p.id)?'Shortlisted ✓':'Shortlist'}</button></div>`
  :`<div class="row wrap" style="margin-top:10px"><button class="btn grn" data-a="signfa:${p.id}">Sign · ${money(faFee(p))}</button><button class="btn" data-a="shortp:${p.id}">${S.me.short.includes(p.id)?'Shortlisted ✓':'Shortlist'}</button></div>`}
  ${ed?`<details style="margin-top:14px"><summary class="b" style="cursor:pointer;min-height:44px;display:flex;align-items:center">Player Editor</summary><div class="grid2" style="margin-top:8px">${ATT.map(k=>`<label class="f"><span>${AL[k]}</span><input type="number" id="ed_${k}" value="${p[k]}" min="10" max="99"></label><label class="f"><span>${AL[k]} cap</span><input type="number" id="edc_${k}" value="${p.cap[k]}" min="10" max="99"></label>`).join('')}<label class="f"><span>Age</span><input type="number" id="ed_age" value="${p.age}" min="15" max="45"></label><label class="f"><span>Position</span><select id="ed_pos">${POSL.map(x=>`<option ${x===p.pos?'selected':''}>${x}</option>`).join('')}</select></label><label class="f" style="grid-column:1/-1"><span>Name</span><input type="text" id="ed_name" value="${esc(p.name)}" maxlength="30"></label></div><div class="row wrap"><button class="btn grn" data-a="edsave:${p.id}">Save changes</button><button class="btn" data-a="edskill:${p.id}">Roll a random skill</button>${p.tr.length?`<button class="btn" data-a="edclear:${p.id}">Remove all skills</button>`:''}</div></details>`:''}`)}
const pmsg=t=>{const el=$('#pmsg');if(el)el.innerHTML=`<div class="card flat b" style="margin:10px 0 0">${esc(t)}</div>`;else toast(t)};

/* ---------- match page ---------- */
P.match=()=>{const f=myFixtureToday();if(!f&&!LM){S.ui.pg='home';return P.home()}
  if(!LM){const H=S.clubs[f.h],A=S.clubs[f.a];const Lh=pickXI(f.h),La=pickXI(f.a);const sh=strength(f.h,Lh)+homeAdv(f.h),sa=strength(f.a,La);const ph=Math.round(100/(1+Math.exp(-(sh-sa)/5)));
    const xi=L=>L.xi.filter(Boolean).map(p=>`<div class="row sm" style="padding:3px 0"><span class="pos ${p.pos}">${p.pos}</span><span style="flex:1">${p.gem?'💎':''}${esc(p.name)} ${tierDots(p)}</span><b>${L.fc[p.id]}</b></div>`).join('');
    return `<div class="card"><div class="row" style="margin-bottom:10px"><span class="lbl">${LEAGUES[f.lg].n} · Round ${f.r} · ${shortD(f.d)}</span><span class="sp chip r">Matchday</span></div><div class="match"><div>${crest(H,64)}<div class="nm">${esc(H.name)}</div></div><div class="disp" style="font-size:28px">v</div><div>${crest(A,64)}<div class="nm">${esc(A.name)}</div></div></div><div style="margin:14px 0 4px" class="row sm"><span>${H.short} ${ph}%</span><span class="sp">${100-ph}% ${A.short}</span></div><div class="bar rd"><i style="width:${ph}%;background:${H.col}"></i></div><p class="note">Pre-match edge from line-up fit, coach, morale, skills, pitch and home advantage.</p><div class="grid2" style="margin-top:12px"><button class="btn pri" data-a="kickoff">Kick off</button><button class="btn" data-a="simres">Sim to result</button></div></div>
    <div class="grid2"><div class="card"><div class="lbl">${esc(H.short)} · ${Lh.form} · ${Lh.tac}</div>${xi(Lh)}</div><div class="card"><div class="lbl">${esc(A.short)} · ${La.form} · ${La.tac}</div>${xi(La)}</div></div>`}
  const H=S.clubs[LM.f.h],A=S.clubs[LM.f.a];
  if(LM.done)return matchSummary();
  return `<div class="score"><div><span style="background:${H.col}">${H.short}</span><span id="sc">${LM.score[0]}-${LM.score[1]}</span><span style="background:${A.col}">${A.short}</span><span id="mn" style="color:#ff8a6a">${Math.floor(LM.min)}'</span></div></div><div class="pitchwrap"><canvas id="cv"></canvas></div><div class="tick" id="tk"><b id="tkm">0'</b><span id="tkt">The teams are out.</span></div><div class="ctrl"><button data-a="pause" id="pb" aria-label="Pause">${LM.paused?'▶':'❚❚'}</button>${[1,2,4,8].map(s=>`<button class="${LM.speed===s?'on':''}" data-a="spd:${s}">${s}x</button>`).join('')}<button class="sp" style="font-size:15px;padding:0 12px;background:var(--goldbg);color:var(--gold)" data-a="simres">Sim to result</button></div><div class="card"><div class="lbl">Commentary</div><div class="log" id="lg"></div></div>`};
function matchSummary(){const f=LM.f,r=LM.r,H=S.clubs[f.h],A=S.clubs[f.a];const home=f.h===S.me.cid;const gf=home?r.gh:r.ga,ga=home?r.ga:r.gh;const res=gf>ga?'Win':gf<ga?'Defeat':'Draw';
  const CD={};r.cards.forEach(c=>CD[c.pid]=c.c==='Y'?'🟨':'🟥');
  const rows=L=>L.xi.filter(Boolean).sort((a,b)=>(f.rt[b.id]||0)-(f.rt[a.id]||0)).map(p=>`<div class="row sm" style="padding:3px 0"><span class="pos ${p.pos}">${p.pos}</span><span style="flex:1">${esc(p.name)} ${CD[p.id]||''}</span><b style="color:${f.rt[p.id]>=7.5?'var(--grn)':f.rt[p.id]<6?'var(--red2)':'inherit'}">${(f.rt[p.id]||0).toFixed(1)}</b></div>`).join('');
  const sc=s=>r.ev.filter(e=>e.side===s).map(e=>`${last(S.P[e.sc]?.name||'?')} ${e.m}'${e.pen?' (pen)':''}`).join(', ')||'—';
  return `<div class="hero" style="background:${gf>ga?'var(--grn)':gf<ga?'var(--red)':'#5d635f'}"><div class="lbl">Full-time · ${res}</div><div class="match" style="margin-top:8px"><div>${crest(H,54)}<div class="nm">${esc(H.name)}</div><div class="sm">${esc(sc('h'))}</div></div><div class="disp" style="font-size:52px">${r.gh}-${r.ga}</div><div>${crest(A,54)}<div class="nm">${esc(A.name)}</div><div class="sm">${esc(sc('a'))}</div></div></div></div>
  ${r.act.length?`<div class="card">${r.act.map(a=>`<div class="sm">✨ ${esc(S.P[a.pid]?.name)} activated ${skPill(a.sid)}</div>`).join('')}</div>`:''}
  <div class="card"><div class="grid4" style="text-align:center"><div><div class="lbl">Possession</div><div class="b">${r.poss}% - ${100-r.poss}%</div></div><div><div class="lbl">Shots</div><div class="b">${r.shH} - ${r.shA}</div></div><div><div class="lbl">Cards</div><div class="b">${r.cards.filter(c=>c.side==='h').length} - ${r.cards.filter(c=>c.side==='a').length}</div></div><div><div class="lbl">Crowd</div><div class="b">${f.att?f.att.toLocaleString():'away'}</div></div></div></div>
  <div class="grid2"><div class="card"><div class="lbl">${esc(H.short)} ratings</div>${rows(r.Lh)}</div><div class="card"><div class="lbl">${esc(A.short)} ratings</div>${rows(r.La)}</div></div><button class="btn pri wide" data-a="donematch">Done</button>`}

/* ---------- continue / run ---------- */
async function runDays(mode){if(RUN)return;RUN={stop:false,lines:[]};RUNMODE=null;let reason='';
  const draw=()=>modal(`<div class="row" style="margin-bottom:6px"><span class="mi" style="background:var(--card2)">📅</span><div><div class="lbl">${fmtD(S.d)}</div><h2>Simulating</h2></div><span class="sp chip g">${mode==='cont'?'Stops at mail':'Stops at next match'}</span></div><div class="runlist">${RUN.lines.slice(-8).reverse().map(l=>`<div class="li"><span style="width:84px" class="disp">${l.d}</span><span style="flex:1"><span class="b">${esc(l.t)}</span><br><span class="sm mut">${esc(l.s)}</span></span></div>`).join('')}</div><button class="btn wide" style="margin-top:12px" data-a="stoprun">❚❚ Stop here</button>`);
  draw();let guard=0;
  while(!RUN.stop&&guard++<400){
    if(myFixtureToday()){reason='match';break}
    const games=S.fx.filter(f=>f.d===S.d&&f.hs===null).length;simOthersToday();S._stop=false;const before=S.mail[0]?.id;advanceDay();
    const newM=[];for(const m of S.mail){if(m.id===before)break;newM.push(m)}const o=dobj(S.d);
    RUN.lines.push({d:`${WD[o.wd]} ${o.day} ${MON[o.m]}`,t:newM.length?newM[0].title:games?'Matchday elsewhere':o.day===1?'Wages and bills settled':'Quiet day at the club',s:newM.length?newM[0].from:games?`${games} games played around the leagues`:o.day===1?'Payroll and running costs':'Nothing needed you.'});draw();
    if(S._seasonEnd){S._seasonEnd=false;reason='season';break}
    if(S._stop&&mode==='cont'){reason='mail';break}
    await sleep(mode==='cont'?110:26);
  }
  RUN=null;closeModal();save();
  if(reason==='match'){go('match')}else if(reason==='mail'||reason==='season'){if(reason==='mail')RUNMODE=mode;const m=S.mail.find(m=>!m.done)||S.mail[0];render();if(m)openMail(m.id)}else render();}
function skipSeason(){const s=S.season;let g=0;while(S.season===s&&g++<400){const f=myFixtureToday();if(f)applyMatch(f,simMatch(f));simOthersToday();advanceDay()}S._seasonEnd=false;save();go('home');toast('Season complete. Check your mail for the review.')}

/* ---------- start screen ---------- */
function dino(sz){const px=['....GGGG....','...GGGGGG...','...GwkGGG...','...GGGGGG.SS','....GGGG..SS','..GGGGGGG.SS','.GGGGGGGGGS.','GGGGGGGGGG..','G.GGGGGGG...','...GG..GG...','...GG..GG...','..OOO..OOO..'];const col={G:'#3fcf7d',w:'#fff',k:'#111',S:'#e2412a',O:'#17191a'};let r='';px.forEach((row,y)=>[...row].forEach((ch,x)=>{if(col[ch])r+=`<rect x="${x}" y="${y}" width="1.02" height="1.02" fill="${col[ch]}"/>`}));return `<svg class="dino" viewBox="0 0 12 12" width="${sz}" height="${sz}" aria-label="Lophus the dinosaur">${r}<circle cx="10.5" cy="10.5" r="1.4" fill="#fff" stroke="#111" stroke-width=".25"/></svg>`}
function withW(W,fn){const keep=S,ksq=SQ;S=W;SQ=null;try{return fn()}finally{S=keep;SQ=ksq}}
function startScreen(){if(!TMP){const keep=S;createWorld();TMP=S;S=keep}const W=TMP;const lg=TMP.ui.st!=null?+TMP.ui.st:3;const L=LEAGUES[lg];
  const clubs=Object.values(W.clubs).filter(c=>c.lg===lg).sort((a,b)=>b.rep-a.rep);
  $('#top').style.display='none';$('#nav').style.display='none';
  V.style.padding='0';V.innerHTML=`<div class="startbg"><div style="max-width:720px;margin:0 auto"><div class="row" style="gap:16px">${dino(84)}<div><div style="opacity:.85;font-weight:600">Season 2027/28</div><h1 style="font-size:clamp(40px,9vw,64px)">Lophus Football Fun</h1></div></div><p style="font-size:18px;max-width:560px">Football meets fantasy. Six countries, ten leagues, ${Object.keys(W.clubs).length} clubs. You're the manager: hire the coach, sign players with rare skills, raise your club's gem, fuse skills in the Lab and chase the Golden Orb.</p>
  <div class="card"><label class="f"><span>Your name, manager</span><input type="text" id="mgr" value="${esc(TMP.ui.mgr||'Daryl')}" maxlength="24"></label><div class="lbl" style="margin-bottom:6px">Country</div><div class="tabs">${Object.keys(NATS).map(n=>`<button class="${L.nat===n?'on':''}" data-a="stn:${n}">${NATS[n]}</button>`).join('')}</div>${L.nat==='en'?`<div style="margin-bottom:6px">${LEAGUES.map((x,i)=>x.nat==='en'?`<button class="pill ${lg===i?'on':''}" data-a="st:${i}">${x.tier}. ${x.n}</button>`:'').join('')}</div>`:''}<p class="sm mut">${esc(L.n)} · ${L.size} clubs. Pick your club. Starting budget ${money(START[(L.nat==='en'?L.tier:(L.q>=70?1:2))-1])}${L.big?' (elite clubs get 2.5×)':''}.</p>${clubs.map(c=>withW(W,()=>`<button class="li" data-a="pickclub:${c.id}">${crest(c,34)}<span style="flex:1"><span class="b">${esc(c.name)}</span><br><span class="sm mut">${esc(c.ground)} · founded ${c.founded}</span><br><span class="chip ${statusOf(c)[1]}">${statusOf(c)[0]}</span></span><span class="sm mut">rep ${c.rep}</span><span class="ovr">${avgOvr(c.id)}</span></button>`)).join('')}<button class="btn sm" style="margin-top:10px" data-a="reroll">🎲 Generate a new world</button></div></div></div>`
}
